<?php
require __DIR__.'/bootstrap.php';
$token=$_GET['id']??'';$s=$db->prepare("SELECT d.*,p.nome paciente,m.nome medico,m.crm,m.uf FROM documentos d JOIN pacientes p ON p.id=d.paciente_id JOIN medicos m ON m.id=d.medico_id WHERE d.token_validacao=? LIMIT 1");$s->execute([$token]);$d=$s->fetch(PDO::FETCH_ASSOC);
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Validação de documento</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="main" style="margin:0;width:100%;max-width:900px;margin:auto"><div class="card" style="margin-top:60px"><h1>Validação de documento médico</h1><?php if(!$d):?><p>Documento não localizado ou código inválido.</p><?php else:?><p><span class="badge"><?=h($d['status']==='cancelado'?'CANCELADO':'VÁLIDO')?></span></p><p><b>Número:</b> <?=h($d['numero'])?></p><p><b>Tipo:</b> <?=h(ucfirst($d['tipo']))?></p><p><b>Paciente:</b> <?=h(mb_substr($d['paciente'],0,3).'••••')?></p><p><b>Médico:</b> <?=h($d['medico'])?> — CRM <?=h($d['crm'])?>/<?=h($d['uf'])?></p><p><b>Emissão:</b> <?=h($d['emitido_em']?:'Não emitido')?></p><p class="muted">Esta página confirma a existência e o status do documento. Informações clínicas não são exibidas.</p><?php endif;?></div></main></body></html>